INSERT INTO `directorate_histories` (`id`, `title`, `introduction`, `content`, `main_image`, `founding_year`, `is_active`, `updated_at`) VALUES
(1, 'تاريخ المديرية', 'تُعد مديرية الخدمات الجامعية سطيف من أقدم المديريات في الجزائر، حيث تأسست عام 1978 بهدف توفير الخدمات الأساسية للطلبة والموظفين.\r\n\r\nعلى مر السنين، تطورت المديرية لتصبح مؤسسة رائدة في تقديم الخدمات الجامعية بمعايير عالية الجودة.', 'البداية والتأسيس\r\n\r\nتأسست مديرية الخدمات الجامعية سطيف في عام 1978، في مرحلة كانت فيها الجامعة الجزائرية تشهد نمواً متسارعاً. \r\n\r\nكانت البدايات متواضعة، حيث اقتصرت الخدمات على توفير الإقامة والإطعام لعدد محدود من الطلبة.\r\n\r\nالتطور والنمو\r\n\r\nمع زيادة عدد الطلبة، توسعت المديرية بشكل كبير:\r\n- افتتاح مطاعم جامعية جديدة\r\n- بناء أحياء جامعية حديثة\r\n- تحسين جودة الخدمات المقدمة\r\n\r\nالحاضر والمستقبل\r\n\r\nاليوم، تخدم المديرية آلاف الطلبة، وتسعى دائماً لتحسين خدماتها ومواكبة التطور التكنولوجي.', 'history/Flat_Responsive_Bootstrap_3__Wordpress.jpg', 1970, 1, '2025-11-11 11:17:48');
