(1, 'قسم الموارد البشرية', 'ksm-lmord-lbshry', 'قسم يهتم بشؤون الموظفين ومسارهم المهني من درجات وتوظيف وترقية', 'departements/drh.jpg', 'جمال سهام', 'sihem@example.com', '0699592820', NULL, 1, 1, '2025-11-10 11:13:06', '2025-11-10 11:13:06');
INSERT INTO `services` (`id`, `title`, `slug`, `service_type`, `short_description`, `detailed_description`, `main_image`, `icon`, `requirements`, `how_to_apply`, `contact_info`, `is_active`, `featured`, `display_order`, `created_at`, `updated_at`) VALUES
(1, 'النقل الجامعي المجاني', 'lnkl-lgmaay-lmgny', 'transport', 'توفر المديرية خدمة النقل المجاني لجميع الطلبة من وإلى الجامعة عبر حافلات مريحة ومجهزة', 'تقدم مديرية الخدمات الجامعية خدمة النقل المجاني لجميع الطلبة المسجلين في الجامعة.\r\n\r\nتشمل الخدمة:\r\n- حافلات حديثة ومكيفة\r\n- خطوط نقل متعددة تغطي كل مناطق سطيف\r\n- مواعيد منتظمة صباحاً ومساءً\r\n- سائقون محترفون ومدربون\r\n\r\nالهدف من الخدمة هو تسهيل تنقل الطلبة وتوفير وقتهم وجهدهم.', 'services/transport.jpg', 'fa-info-circle', '- أن يكون الطالب مسجلاً في الجامعة\r\n- تقديم بطاقة الطالب عند الصعود\r\n- الالتزام بالمواعيد المحددة\r\n- احترام قواعد السلامة داخل الحافلة', '1. التوجه لمصلحة النقل بالمديرية\r\n2. تعبئة استمارة الاشتراك\r\n3. تقديم نسخة من بطاقة الطالب\r\n4. الحصول على بطاقة النقل', 'مصلحة النقل\r\nالهاتف: 036 xx xx xx\r\nالبريد الإلكتروني: transport@univ-setif.dz\r\nالمكتب: الطابق الأرضي - المديرية', 1, 1, 1, '2025-11-11 13:13:06', '2025-11-11 13:13:06'),
(2, 'السكن الجامعي', 'lskn-lgmaay', 'housing', 'توفير سكن جامعي مريح وآمن لجميع الطلبة المستحقين في أحياء جامعية مجهزة بكل المرافق الضرورية', 'تدير المديرية عدة أحياء جامعية توفر سكناً لآلاف الطلبة.\r\n\r\nالمرافق المتوفرة:\r\n- غرف مجهزة بأسرّة وخزانات\r\n- مرافق صحية نظيفة\r\n- قاعات للمطالعة\r\n- اتصال بالإنترنت\r\n- أمن على مدار الساعة\r\n\r\nنسعى لتوفير بيئة مريحة تساعد الطلبة على التفوق الدراسي.', 'services/amphi.jpg', 'fa-info-circle', '- الأولوية للطلبة من خارج الولاية\r\n- المعدل الدراسي لا يقل عن 10/20\r\n- الوضعية الاجتماعية (حسب الدخل)\r\n- عدم وجود سكن قريب من الجامعة', '1. التسجيل الإلكتروني عبر منصة PROGRES\r\n2. رفع الوثائق المطلوبة\r\n3. انتظار دراسة الملف\r\n4. استلام قرار القبول\r\n5. التوجه للحي الجامعي المحدد', 'مصلحة الإيواء\r\nالهاتف: 036 xx xx xx\r\nالبريد: housing@univ-setif.dz', 1, 0, 2, '2025-11-11 13:15:38', '2025-11-11 13:15:38'),
(3, 'مصلحة الإيواء الهاتف: 036 xx xx xx البريد: housing@univ-setif.dz', 'mslh-lyo-lhtf-036-xx-xx-xx-lbryd-housinguniv-setifdz', 'catering', 'وجبات غذائية متوازنة ومتنوعة في مطاعم جامعية حديثة بأسعار رمزية في متناول جميع الطلبة', 'تدير المديرية عدة مطاعم جامعية تقدم وجبات يومية للطلبة.\r\n\r\nالوجبات المتوفرة:\r\n- وجبة الفطور (7:00 - 9:00)\r\n- وجبة الغداء (12:00 - 14:00)\r\n- وجبة العشاء (18:00 - 20:00)\r\n\r\nنحرص على:\r\n- جودة الطعام\r\n- النظافة التامة\r\n- التنوع في القوائم\r\n- احترام المعايير الصحية', 'services/b1-27.jpg', 'fa-info-circle', '- بطاقة الطالب سارية المفعول\r\n- بطاقة المطعم (للمستفيدين من المنحة)\r\n- أو الدفع النقدي (30 دج للوجبة)', 'للحصول على بطاقة المطعم المجانية:\r\n1. تقديم ملف المنحة\r\n2. استلام قرار الاستفادة\r\n3. أخذ بطاقة المطعم من المصلحة', 'مصلحة الإطعام\r\nالهاتف: 036 xx xx xx', 1, 1, 0, '2025-11-11 13:17:59', '2025-11-11 13:17:59');
