INSERT INTO `faqs` (`id`, `category_id`, `question`, `answer`, `order`, `is_active`, `views_count`, `created_at`, `updated_at`) VALUES
(1, 1, 'ما هي مديرية الخدمات الجامعية؟', 'مديرية الخدمات الجامعية هي مؤسسة عمومية ذات طابع إداري، تُعنى بتوفير الخدمات الاجتماعية للطلبة الجامعيين.\r\n\r\nتشمل مهامها:\r\n- توفير السكن الجامعي\r\n- تقديم وجبات الإطعام\r\n- تنظيم النقل الجامعي\r\n- منح الإعانات المالية للطلبة المستحقين', 0, 1, 0, '2025-11-12 13:13:01', '2025-11-12 13:13:01'),
(2, 2, 'كيف أحصل على المنحة الجامعية؟', 'للحصول على المنحة الجامعية:\r\n\r\n1. التسجيل عبر منصة PROGRES في الآجال المحددة (سبتمبر - أكتوبر)\r\n2. ملء استمارة المنحة إلكترونياً\r\n3. رفع الوثائق المطلوبة:\r\n   - شهادة الدخل الشهري للعائلة\r\n   - شهادة الإقامة\r\n   - كشف النقاط\r\n   - شهادة الميلاد\r\n4. طباعة الملف وتقديمه في مصلحة المنح\r\n5. انتظار دراسة الملف والقرار\r\n\r\nملاحظة: تُعطى الأولوية للطلبة ذوي الدخل المحدود والنجاح الدراسي.', 0, 1, 0, '2025-11-12 13:13:53', '2025-11-12 13:13:53'),
(3, 3, 'ما هي شروط الاستفادة من السكن الجامعي؟', 'شروط الاستفادة من السكن الجامعي:\r\n\r\n1. أن يكون الطالب مسجلاً فعلياً في الجامعة\r\n2. الأولوية للطلبة من خارج الولاية\r\n3. المعدل الدراسي لا يقل عن 10/20\r\n4. الوضعية الاجتماعية (حسب دخل العائلة)\r\n5. عدم وجود سكن قريب من الجامعة (أقل من 50 كلم)\r\n6. عدم التكرار أكثر من مرة واحدة في السنة\r\n\r\nالتقديم يكون عبر منصة PROGRES خلال شهر سبتمبر.', 0, 1, 0, '2025-11-12 13:15:32', '2025-11-12 13:15:32');
